var nextWindowId = 1;
var defaultOptions2 = {
  title: "Electrobun",
  frame: {
    x: 0,
    y: 0,
    width: 800,
    height: 600
  },
  url: "https://electrobun.dev",
  html: null,
  preload: null,
  renderer: "native",
  titleBarStyle: "default",
  navigationRules: null
};
var BrowserWindowMap2 = {};

class BrowserWindow {
  id = nextWindowId++;
  ptr;
  title = "Electrobun";
  state = "creating";
  url = null;
  html = null;
  preload = null;
  renderer;
  frame = {
    x: 0,
    y: 0,
    width: 800,
    height: 600
  };
  webviewId;
  constructor(options = defaultOptions2) {
    this.title = options.title || "New Window";
    this.frame = options.frame ? { ...defaultOptions2.frame, ...options.frame } : { ...defaultOptions2.frame };
    this.url = options.url || null;
    this.html = options.html || null;
    this.preload = options.preload || null;
    this.renderer = options.renderer === "cef" ? "cef" : "native";
    this.navigationRules = options.navigationRules || null;
    this.init(options);
  }
  init({
    rpc,
    styleMask,
    titleBarStyle
  }) {
    this.ptr = ffi.request.createWindow({
      id: this.id,
      title: this.title,
      url: this.url || "",
      frame: {
        width: this.frame.width,
        height: this.frame.height,
        x: this.frame.x,
        y: this.frame.y
      },
      styleMask: {
        Borderless: false,
        Titled: true,
        Closable: true,
        Miniaturizable: true,
        Resizable: true,
        UnifiedTitleAndToolbar: false,
        FullScreen: false,
        FullSizeContentView: false,
        UtilityWindow: false,
        DocModalWindow: false,
        NonactivatingPanel: false,
        HUDWindow: false,
        ...styleMask || {},
        ...titleBarStyle === "hiddenInset" ? {
          Titled: true,
          FullSizeContentView: true
        } : {}
      },
      titleBarStyle: titleBarStyle || "default"
    });
    BrowserWindowMap2[this.id] = this;
    const webview = new BrowserView({
      url: this.url,
      html: this.html,
      preload: this.preload,
      renderer: this.renderer,
      frame: {
        x: 0,
        y: 0,
        width: this.frame.width,
        height: this.frame.height
      },
      rpc,
      windowId: this.id,
      navigationRules: this.navigationRules
    });
    console.log("setting webviewId: ", webview.id);
    this.webviewId = webview.id;
  }
  get webview() {
    return BrowserView.getById(this.webviewId);
  }
  static getById(id) {
    return BrowserWindowMap2[id];
  }
  setTitle(title) {
    this.title = title;
    return ffi.request.setTitle({ winId: this.id, title });
  }
  close() {
    return ffi.request.closeWindow({ winId: this.id });
  }
  focus() {
    return ffi.request.focusWindow({ winId: this.id });
  }
  on(name, handler) {
    const specificName = `${name}-${this.id}`;
    eventEmitter_default.on(specificName, handler);
  }
}

// src/bun/index.ts
var bioParsers = __toESM(require_parsers(), 1);
var rpc = BrowserView.defineRPC({
  handlers: {
    requests: {
      ove_saveFile: async ({ filePath, sequenceDataToSave, isSaveAs }) => {
        console.log("RPC: ove_saveFile", filePath);
        try {
          let content;
          if (filePath.endsWith(".json")) {
            content = JSON.stringify(sequenceDataToSave, null, 2);
          } else if (filePath.endsWith(".fasta")) {
            content = bioParsers.jsonToFasta(sequenceDataToSave);
          } else if (filePath.endsWith(".bed")) {
            content = bioParsers.jsonToBed(sequenceDataToSave);
          } else {
            content = bioParsers.jsonToGenbank(sequenceDataToSave);
          }
          await Bun.write(filePath, content);
          return { success: true };
        } catch (e) {
          console.error(e);
          throw e;
        }
      },
      ove_showSaveDialog: async (opts) => {
        console.log("RPC: ove_showSaveDialog", opts);
        const filename = opts.defaultPath ? opts.defaultPath.split("/").pop() : "sequence.gb";
        return `${process.cwd()}/${filename}`;
      }
    },
    messages: {
      log: (msg) => console.log("Renderer Log:", msg)
    }
  }
});
var mainWindow = new BrowserWindow({
  title: "Open Vector Editor",
  url: "views://mainview/index.html",
  frame: {
    width: 1000,
    height: 800,
    x: 100,
    y: 100
  },
  rpc
});
